 * Per-user, per-kind delivery matrix consulted before every fan-out.
 */
import { and, eq } from "drizzle-orm";
import { getDb, notificationPreferences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, toPreference } from "./_mappers";
import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
import type { OrgId, UserId } from "@/types/common";
import type {
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export async function listPreferences(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly NotificationPreference[]> {
  const rows = getDb()
    .select()
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.userId, userId),
      ),
    )
    .all();
  return rows.map(toPreference);
}

/**
 * `null` means "no explicit row" — the fan-out then falls back to the default
 * channel set rather than treating the absence as "everything off".
 */
export async function getPreference(
  orgId: OrgId,
  userId: UserId,
  kind: NotificationKind,
): Promise<NotificationPreference | null> {
  const row = getDb()
    .select()
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.userId, userId),
        eq(notificationPreferences.kind, kind),
      ),
    )
    .get();
  return row ? toPreference(row) : null;
}

export async function upsertPreference(
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  const row = getDb()
    .insert(notificationPreferences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      kind: input.kind,
      inApp: input.inApp,
      email: input.email,
      digestOnly: input.digestOnly,
    })
    .onConflictDoUpdate({
      target: [
        notificationPreferences.orgId,
        notificationPreferences.userId,
        notificationPreferences.kind,
      ],
      set: {
        inApp: input.inApp,
        email: input.email,
        digestOnly: input.digestOnly,
      },
    })
    .returning()
    .get();

  return toPreference(row);
}

/** Distinct users with at least one `digestOnly` preference in this org. */
export async function listDigestSubscribers(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .selectDistinct({ userId: notificationPreferences.userId })
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.digestOnly, true),
      ),
    )
    .all();

  return rows.map((row) => brandId<UserId>(row.userId));
}
"use server";

/**
 * Marks the whole inbox read.
 *
 * Owner D. Returns the number of rows touched so the bell badge can be updated
 * without a second round trip.
 *
 * Must call (do not reimplement): markAllNotificationsReadSchema, can,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { markAllNotificationsReadSchema } from "@/schemas/notification";
import { markAllRead } from "@/server/services/notification-service";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";

type MarkAllReadInput = { orgId: OrgId };

const run = withAction<typeof markAllNotificationsReadSchema, number>(
  markAllNotificationsReadSchema,
  async (raw, actor) => {
    const input = raw as MarkAllReadInput;

    const allowed = can(actor, "notification:manage", {
      kind: "notification",
      orgId: input.orgId,
      recipientId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("notification:manage");
    }

    const count = await markAllRead(actor, input.orgId);
    revalidateTagged(["notifications"], CACHE_PROFILES.seconds);
    return count;
  },
  { revalidate: ["notifications"], cacheProfile: "seconds" },
);

export async function markAllNotificationsReadAction(
  raw: unknown,
): Promise<ActionResult<number>> {
  return run(raw);
}
"use server";

/**
 * Marks one notification read.
 *
 * Owner D. `notification:read` is granted to every role, but the resource
 * carries `recipientId` — the ownership escalation inside `can()` is what stops
 * one member marking another member's inbox.
 *
 * Must call (do not reimplement): markNotificationReadSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  markNotificationReadSchema,
  type MarkNotificationReadInput,
} from "@/schemas/notification";
import { markRead } from "@/server/services/notification-service";
import type { ActionResult } from "@/types/api";
import type { Notification } from "@/types/notification";

const run = withAction<typeof markNotificationReadSchema, Notification>(
  markNotificationReadSchema,
  async (raw, actor) => {
    const input = raw as MarkNotificationReadInput;

    const allowed = can(actor, "notification:read", {
      kind: "notification",
      orgId: input.orgId,
      recipientId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("notification:read");
    }

    const notification = await markRead(actor, input);
    revalidateTagged(["notifications"], CACHE_PROFILES.seconds);
    return notification;
  },
  { revalidate: ["notifications"], cacheProfile: "seconds" },
);

export async function markNotificationReadAction(
  raw: unknown,
): Promise<ActionResult<Notification>> {
  return run(raw);
}
"use server";

/**
 * Updates one notification preference row.
 *
 * Owner D. `digestOnly` is only meaningful while the `digest_email` flag is on
 * for the organization; asking for it otherwise would strand the notification
 * in a digest that never gets sent, so the flag is checked here.
 *
 * Must call (do not reimplement): updateNotificationPreferenceSchema,
 * isEnabled, getActor, toActionResult
 */

import { FeatureUnavailableError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import {
  updateNotificationPreferenceSchema,
  type UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { updatePreference } from "@/server/services/notification-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { NotificationPreference } from "@/types/notification";

const run = withAction<
  typeof updateNotificationPreferenceSchema,
  NotificationPreference
>(
  updateNotificationPreferenceSchema,
  async (raw, actor) => {
    const input = raw as UpdateNotificationPreferenceInput;

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    const context = buildFlagContext(actor, organization);

    if (input.digestOnly && !isEnabled("digest_email", context)) {
      throw new FeatureUnavailableError("digest_email");
    }

    const preference = await updatePreference(actor, input);
    revalidateTagged(["notification-preferences"], CACHE_PROFILES.hours);
    return preference;
  },
  { revalidate: ["notification-preferences"], cacheProfile: "hours" },
);

export async function updateNotificationPreferenceAction(
  raw: unknown,
): Promise<ActionResult<NotificationPreference>> {
  return run(raw);
}

